import test from 'node:test';import assert from 'node:assert/strict';import {ask,validateOutput,answer,requestBody,validateQuestion} from '../../reda-2/engine/dialogue.mjs';
const plan={patientName:'Must not leave',clinicianNote:'Private note',goal:'Gå till affären',exercises:[{name:'Benspark',why:'Din sparade anledning',instructions:['Din sparade instruktion'],side:'right',dose:{sets:2,reps:8,label:'2 × 8',rest:60}}]};
test('model receives minimized saved facts, strict schema and no storage request',()=>{const b=requestBody('configured-model','Varför benspark?',plan);assert.equal(b.store,false);assert.equal(b.text.format.strict,true);assert.ok(!JSON.stringify(b).includes('Must not leave'));assert.ok(!JSON.stringify(b).includes('Private note'));});
test('model cannot introduce a dose or action even with a well-formed routing result',()=>{const before=JSON.stringify(plan),raw={intent:'dose',exerciseIndex:0,reports:[]};assert.deepEqual(answer(raw,plan).paragraphs,['2 × 8','Höger sida.','Ordinerad vila mellan omgångarna: 60 sekunder.']);assert.equal(answer(raw,plan).canChangePrescription,false);assert.throws(()=>validateOutput({...raw,dose:100},'Dubbla dosen',plan));assert.equal(JSON.stringify(plan),before)});
test('unsupported quotes, contradictory duplicates and foreign exercise indexes are rejected',()=>{const raw={intent:'report',exerciseIndex:null,reports:[{field:'nextDay',value:'worse',quote:'mer ont'}]};assert.equal(validateOutput(raw,'Jag har mer ont',plan),raw);assert.throws(()=>validateOutput(raw,'Jag har inte ont',plan));assert.throws(()=>validateOutput({...raw,reports:[...raw.reports,...raw.reports]},'mer ont',plan));assert.throws(()=>validateOutput({...raw,exerciseIndex:3},'mer ont',plan));assert.throws(()=>validateQuestion('19900101-1234 gör ont'))});
test('missing configuration never calls a model or pretends to answer',async()=>{let calls=0;const r=await ask({question:'Varför?',plan,fetcher:()=>calls++});assert.equal(r.available,false);assert.equal(calls,0)});
test('verified provider response is routed to the exact saved instruction',async()=>{const result=await ask({question:'Hur gör jag benspark?',plan,model:'configured-model',apiKey:'fictional-key',fetcher:async()=>({ok:true,json:async()=>({status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify({intent:'execution',exerciseIndex:0,reports:[]})}]}],usage:{input_tokens:80,output_tokens:20}})})});assert.equal(result.available,true);assert.deepEqual(result.paragraphs,['Din sparade instruktion']);assert.equal(result.usage.inputTokens,80)});
test('provider refusal, truncated JSON and transport failure have no clinical side effects',async()=>{for(const data of [{status:'incomplete',output:[]},{status:'completed',output:[{type:'message',content:[{type:'refusal',refusal:'no'}]}]},{status:'completed',output:[{type:'message',content:[{type:'output_text',text:'bad json'}]}]}])await assert.rejects(ask({question:'Min fråga',plan,model:'configured-model',apiKey:'fictional-key',fetcher:async()=>({ok:true,json:async()=>data})}));await assert.rejects(ask({question:'Min fråga',plan,model:'configured-model',apiKey:'fictional-key',endpoint:'https://untrusted.invalid/v1/responses'}))});
